<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>Administrative areas</h2><p>Each area is identified by its mouza, upazila and district.</p></div><IconButton icon="add" label="Create area" @click="open(null)"/></div><div class="glass-panel"><div v-if="error" class="inline-alert">{{error}}</div><div v-if="loading" class="state-message">Loading areas…</div><div v-else-if="!result.items?.length" class="state-message">No areas have been created.</div><div v-else class="table-scroll"><table class="glass-table"><thead><tr><th>Mouza</th><th>Upazila</th><th>District</th><th></th></tr></thead><tbody><tr v-for="a in result.items" :key="a.id"><td><b>{{a.mouza}}</b></td><td>{{a.upazila}}</td><td>{{a.district}}</td><td class="actions"><IconButton icon="edit" label="Edit area" @click="open(a)"/></td></tr></tbody></table></div><div class="pagination"><span>Page {{result.page||1}} of {{result.totalPages||0}}</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div></div><div v-if="modal" class="glass-panel inline-form-card"><form @submit.prevent="save"><div class="modal-heading"><h3>{{editing?'Update area':'Create area'}}</h3><IconButton icon="cancel" label="Close" @click="modal=false"/></div><FormField label="Mouza"><input v-model="form.mouza" required maxlength="120"/></FormField><FormField label="Upazila"><input v-model="form.upazila" required maxlength="120"/></FormField><FormField label="District"><input v-model="form.district" required maxlength="120"/></FormField><p v-if="error" class="inline-alert">{{error}}</p><div class="modal-actions"><IconButton icon="cancel" label="Cancel" @click="modal=false"/><IconButton icon="save" label="Save area" type="submit"/></div></form></div></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{platformApi}from'@/services/platform';import IconButton from'@/components/ui/IconButton.vue';import FormField from'@/components/ui/FormField.vue';const result=ref<any>({items:[]}),loading=ref(false),error=ref(''),modal=ref(false),editing=ref<any>(null),form=ref<any>({mouza:'',upazila:'',district:''});async function load(page=1){loading.value=true;try{result.value=(await platformApi.areas(page)).data;error.value=''}catch(e:any){error.value=e.response?.data?.detail||'Could not load areas'}finally{loading.value=false}}function open(a:any){editing.value=a;form.value=a?{mouza:a.mouza,upazila:a.upazila,district:a.district}:{mouza:'',upazila:'',district:''};modal.value=true}async function save(){try{if(editing.value)await platformApi.updateArea(editing.value.id,form.value);else await platformApi.createArea(form.value);modal.value=false;await load(result.value.page||1)}catch(e:any){error.value=e.response?.data?.detail||'Could not save area'}}onMounted(()=>load());</script>
